def quick_sort(arr):
    if len(arr) < 2:
        return arr
    else:
        pivot = arr[0]
        less = [i for i in arr[1:] if i <= pivot]
        greater = [i for i in arr[1:] if i > pivot]
        return quick_sort(less) + [pivot] + quick_sort(greater)

def sentiment_analysis(documents):
  sentiments = []
  for document in documents:
    sentiment = None
    score = 0
    words = document.split(' ')
    for word in words:
      if word == 'great':
        score += 1
      elif word == 'bad':
        score -= 1
    if score > 0:
      sentiment = 'positive'
    elif score == 0:
      sentiment = 'neutral'
    else:
      sentiment = 'negative'
    sentiments.append(sentiment)
  return sentiments

