class TreeIterator:
    def __init__(self, root):
        self.root = root
        self.stack = []
        self.current = None

    def __iter__(self):
        return self

    def __next__(self):
        # Case 1: there is a left-subtree
        if self.current is None:
            if self.root is not None:
                self.stack.append(self.root)
                self.current = self.root.left
            else:
                # Tree is empty
                raise StopIteration
        # Case 2: there is a right-subtree
        elif self.current.right is not None:
            self.stack.append(self.current.right)
            self.current = self.current.right.left
        # Case 3: there is no right-subtree and no left-subtree
        elif self.stack:
            self.current = self.stack.pop()
        else:
            # It's the end of the traversal
            self.current = None
            raise StopIteration
        return self.current.value

def binary_search(array, target):
    lower = 0
    upper = len(array)
    while lower < upper:
        x = lower + (upper - lower) // 2
        val = array[x]
        if target == val:
            return x
        elif target > val:
            if lower == x:
                break
            lower = x
        elif target < val:
            upper = x
    return -1

