def normalize_matrix(matrix):
    output = []
    m,n = len(matrix), len(matrix[0])
    min_el, max_el = float("inf"), float("-inf")
    for i in range(m):
        for j in range(n):
            min_el = min(matrix[i][j], min_el)
            max_el = max(matrix[i][j], max_el)
    for i in range(m):
        output.append([])
        for j in range(n):
            output[i].append((matrix[i][j]-min_el)/(max_el-min_el))
    return output

def tsp(graph): 

    # Set initial values: 
    best_path = [] 
    best_path_cost = float('Inf') 

    # Iterate through all the possible paths: 
    for i in range(1 << len(graph[0])): 

        # Generate the binary string: 
        path = [] 
        for j in range(len(graph[0])): 
            if (i & (1 << j)) > 0: 
                path.append(j) 

        # Calculate the cost of the path: 
        cost = 0
        k = 0
        for j in range(len(path)): 
            if j+1 < len(path): 
                cost += graph[path[j]][path[j+1]] 
            else: 
                cost += graph[path[j]][path[0]] 

        # Check if the cost of the path is less than the 
        # current best path cost: 
        if cost < best_path_cost: 
            best_path_cost = cost 
            best_path = path 

    return best_path, best_path_cost

