def classifier(doc):
    if doc.text.startswith('http'):
        return 'Website'
    elif doc.text.startswith('www'):
        return 'Website'
    elif '@' in doc.text:
        return 'Email'
    elif '#' in doc.text:
        return 'Hashtag'
    elif doc.is_space:
        return 'Space'
    else:
        doc = nlp(doc.text)
        tokens_no_punct = [token for token in doc if not token.is_punct]
        token_length = len(tokens_no_punct)
        if token_length <= 3:
            return 'Short Text'
        elif token_length > 3 and token_length <=15:
            return 'Medium Text'
        elif token_length > 15:
            return 'Long Text'

